import bisect
class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        B = max(nums).bit_length()
        ans = 0
        for b in range(B):
            tails = []
            for x in nums:
                if x >> b & 1:
                    p = bisect.bisect_left(tails, x)
                    if p == len(tails):
                        tails.append(x)
                    else:
                        tails[p] = x
            ans = max(ans, len(tails))
        return ans

