class Solution {
    public int longestSubsequence(int[] nums) {
        int mx = 0;
        for (int x : nums) mx = Math.max(mx, x);
        int B = Integer.SIZE - Integer.numberOfLeadingZeros(mx);
        int ans = 0;
        for (int b = 0; b < B; b++) {
            int[] tails = new int[nums.length];
            int len = 0;
            for (int x : nums) {
                if (((x >> b) & 1) == 1) {
                    int lo = 0, hi = len;
                    while (lo < hi) {
                        int mid = (lo + hi) >>> 1;
                        if (tails[mid] < x) lo = mid + 1; else hi = mid;
                    }
                    tails[lo] = x;
                    if (lo == len) len++;
                }
            }
            ans = Math.max(ans, len);
        }
        return ans;
    }
}

