class Solution {
    public int longestSubsequence(int[] nums) {
        List<List<Integer>> tails = new ArrayList<>();
        for (int i = 0; i < 30; i++) tails.add(new ArrayList<>());
        int ans = 0;
        for (int x : nums) {
            for (int b = 0; b < 30; b++) {
                if (((x >> b) & 1) == 1) {
                    List<Integer> t = tails.get(b);
                    int lo = 0, hi = t.size();
                    while (lo < hi) {
                        int mid = (lo + hi) >>> 1;
                        if (t.get(mid) < x) lo = mid + 1; else hi = mid;
                    }
                    if (lo == t.size()) t.add(x); else t.set(lo, x);
                    ans = Math.max(ans, t.size());
                }
            }
        }
        return ans;
    }
}

